export const introHead=`<style>.brand-intro{display:none}.brand-intro-pending .brand-intro{display:flex;position:fixed;inset:0;z-index:10000;background:#08090a;align-items:center;justify-content:center}.brand-intro-pending{overflow:hidden}</style><script>try{if(!localStorage.getItem('martinez-welcome-v1')&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('brand-intro-pending');window.brandIntroFailsafe=setTimeout(function(){document.documentElement.classList.remove('brand-intro-pending');document.querySelectorAll('[data-intro-inert]').forEach(function(e){e.inert=false;e.removeAttribute('data-intro-inert')})},6000)}}catch(e){}</script>`;
export function introMarkup(){return `<div class="brand-intro" role="dialog" aria-modal="true" aria-label="Welcome to Martinez Logistics"><div class="intro-composition"><svg class="intro-mark" viewBox="0 0 800 447" aria-label="Martinez Logistics LLC Chauffeur Service" role="img"><defs><mask id="parked-mark"><rect width="800" height="447" fill="white"/><path d="M437 165H759V282H442V272L434 257L435 226L437 200Z" fill="black"/></mask><clipPath id="parked-car"><path d="M437 165H759V282H442V272L434 257L435 226L437 200Z"/></clipPath></defs><image class="intro-base" href="/assets/logo.webp" width="800" height="447" mask="url(#parked-mark)"/><g class="intro-car"><image href="/assets/logo.webp" width="800" height="447" clip-path="url(#parked-car)"/></g></svg><div class="intro-horizon"></div><p class="intro-caption">EVERY ARRIVAL BEGINS WITH CARE</p></div><button class="intro-skip" type="button">Skip entrance</button></div>`}
export function startBrandIntro(){
 const root=document.documentElement,overlay=document.querySelector('.brand-intro');if(!overlay)return;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');let timer,fade,previousFocus;
 const finish=()=>{clearTimeout(timer);clearTimeout(window.brandIntroFailsafe);try{localStorage.setItem('martinez-welcome-v1','seen')}catch{}overlay.classList.add('is-leaving');document.querySelectorAll('[data-intro-inert]').forEach(e=>{e.inert=false;e.removeAttribute('data-intro-inert')});fade=setTimeout(()=>{root.classList.remove('brand-intro-pending');overlay.classList.remove('is-playing','is-leaving');previousFocus?.focus({preventScroll:true})},450)};
 const play=()=>{clearTimeout(timer);clearTimeout(fade);previousFocus=document.activeElement;root.classList.add('brand-intro-pending');overlay.classList.remove('is-playing','is-leaving');document.querySelectorAll('body > header,body > main,body > footer,body > .skip').forEach(e=>{if(!e.inert){e.inert=true;e.setAttribute('data-intro-inert','')}});void overlay.offsetWidth;overlay.classList.add('is-playing');overlay.querySelector('button').focus({preventScroll:true});timer=setTimeout(finish,3450)};
 overlay.querySelector('button').addEventListener('click',finish);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&root.classList.contains('brand-intro-pending'))finish()});document.querySelector('[data-replay-entrance]')?.addEventListener('click',()=>{if(!reduced.matches)play()});if(root.classList.contains('brand-intro-pending'))play();reduced.addEventListener('change',()=>{if(reduced.matches&&root.classList.contains('brand-intro-pending'))finish()});
}
